from fractions import Fraction as F
from math import factorial
def bn(n,k):
 r=F(1)
 for i in range(k): r*=F(n-i,i+1)
 return r
def H(g,a,b=4): return {-a-g+j:F(factorial(g))*bn(-a,g-j)*bn(a-b,j)*((-1)**j) for j in range(g+1)}
def op(h,g,Q,sgn):
 o={}
 for e,c in h.items():
  v=e+1+sgn*Q;o[e]=o.get(e,F(0))+c*v;o[e+1]=o.get(e+1,F(0))+c*(v-g)
 return {e:c for e,c in o.items() if c}
def col(g,q,a,br):
 Q=q+2;v=op(H(g,a),g,Q,-1 if br=='-' else 1)
 return v if br=='-' else {e+Q:-c for e,c in v.items()}
def sub(v,w,c):
 for e,x in w.items():
  v[e]=v.get(e,F(0))-c*x
  if not v[e]: del v[e]
def audit(g,q,N,targets):
 labels=[(a,b) for a in range(N+1) for b in '-+']; piv=[]; E=[]; reps=[]
 dep={}
 for lab in labels:
  v=col(g,q,*lab); rep={}
  for i,p in enumerate(piv):
   c=v.get(p,F(0))
   if c:
    sub(v,E[i],c)
    for j,x in reps[i].items(): rep[j]=rep.get(j,F(0))-c*x
  if v:
   p=min(v);z=v[p];v={e:x/z for e,x in v.items()};rep={j:x/z for j,x in rep.items()};idx=len(piv);rep[idx]=rep.get(idx,F(0))+F(1,z);piv.append(p);E.append(v);reps.append(rep)
  else: dep[lab]={j:-x for j,x in rep.items()}
 bas=[lab for lab in labels if lab not in dep]
 cap=[a for a,b in bas if b=='+'];out=[]
 for a in targets:
  rr=dep.get((a,'+'),{});mx=max(map(abs,rr.values()),default=F(1));out.append((a,str(mx),len(rr)))
 return cap,out
for g,q in [(6,3),(6,8),(6,13)]:
